```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();

        let mut message = format!("digest {}: {} item(s) kept", composed.date, kept);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push('\n');
            message.push_str(&entry.title);
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
